import pandas as pd, numpy as np, glob
from scipy.stats import spearmanr

files=glob.glob('../persistent/stock_data/*.csv')
data={}
for f in files:
    s=f.split('/')[-1][:-4]
    if s in ['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']:
        d=pd.read_csv(f,parse_dates=['date']).set_index('date').sort_index()
        data[s]=d.loc[:'2026-07-15']
# one idea: volatility-state conditioned one-day reversal; variants differ only state transform
close=pd.DataFrame({s:d.close for s,d in data.items()})
ret=close.pct_change()
vol20=ret.rolling(20,min_periods=15).std(); vol60=ret.rolling(60,min_periods=40).std()
# normalize recent reversal by risk, then condition on volatility state
variants={
 'highvol_scaled_reversal': -ret*vol20/vol60,
 'lowvol_scaled_reversal': -ret*vol60/vol20,
 'volshock_reversal': -ret*(vol20/vol60-1),
}
fwd=ret.shift(-1)
for name,x in variants.items():
    vals=[]; dates=[]; cov=[]; turnovers=[]; prev=None
    for dt in x.index:
        a=x.loc[dt]; y=fwd.loc[dt]; z=pd.concat([a,y],axis=1).dropna()
        if len(z)>=8:
            vals.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic); dates.append(dt); cov.append(len(z)/15)
            ranks=a.rank(pct=True)
            if prev is not None: turnovers.append(np.mean(abs(ranks-prev)))
            prev=ranks
    ic=np.array(vals); icir=ic.mean()/ic.std(ddof=1)*np.sqrt(252) if len(ic)>1 else np.nan
    print(name, 'dates',len(ic),'avg_n',np.mean(np.array(cov)*15),'IC',ic.mean(),'ICIR',icir,'hit',np.mean(ic>0),'turn',np.nanmean(turnovers),'recent250',ic[-250:].mean() if len(ic)>=250 else np.nan)
    for h in [5,10]:
        yy=close.shift(-h)/close-1; q=[]
        for dt in x.index:
            z=pd.concat([x.loc[dt],yy.loc[dt]],axis=1).dropna()
            if len(z)>=8:q.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
        print(' decay',h,np.nanmean(q))

