import pandas as pd,numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; end=pd.Timestamp('2026-07-15')
P=pd.concat([pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).set_index('date').close.rename(s) for s in U],axis=1,sort=True).loc[:end]
R=P.pct_change(fill_method=None); M=R.median(axis=1)
# rolling beta computed with aligned per-series pairwise moments, then residual 5d cumulative return
F=pd.DataFrame(index=P.index,columns=U,dtype=float)
for s in U:
 x=R[s]; cov=x.rolling(60,min_periods=30).cov(M); vv=M.rolling(60,min_periods=30).var(); b=cov/(vv+1e-12)
 F[s]=(x-b*M).rolling(5,min_periods=5).sum()
Y={h:P.pct_change(h,fill_method=None).shift(-h) for h in [1,5,10]}
for h,y in Y.items():
 q=[]; ns=[]
 for d in F.index:
  z=pd.concat([F.loc[d],y.loc[d]],axis=1).dropna()
  if len(z)>=8 and z.iloc[:,0].nunique()>1:q.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic);ns.append(len(z))
 q=np.array(q);print('h',h,'dates',len(q),'avgN',np.mean(ns),'coverage',sum(ns)/(len(F)*15),'IC',q.mean(),'ICIR',q.mean()/q.std(ddof=1),'hit',(q>0).mean())
q=[]
for d in F.index:
 z=pd.concat([F.loc[d],Y[1].loc[d]],axis=1).dropna()
 if len(z)>=8:q.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
q=np.array(q)
for a,b in [('2020','2022'),('2023','2024'),('2025','2026')]:
 w=[]
 for d in F.loc[a:b].index:
  z=pd.concat([F.loc[d],Y[1].loc[d]],axis=1).dropna()
  if len(z)>=8:w.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
 w=np.array(w);print('regime',a,b,len(w),w.mean(),w.mean()/w.std(ddof=1))
print('turnover',F.rank(axis=1,pct=True).diff().abs().mean(axis=1).mean())

import pandas as pd,numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; end=pd.Timestamp('2026-07-15')
D={s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).set_index('date').sort_index().loc[:end] for s in U}
R=pd.concat({s:D[s].close.pct_change() for s in U},axis=1).sort_index()
# Conditional regime blend: in weak breadth use volatility-scaled residual reversal;
# in calm breadth use short-term momentum. All inputs are lagged at decision cutoff.
med=R.median(axis=1); breadth=(R>0).mean(axis=1)
res=R.sub(med,axis=0)
rev=-res.rolling(3,min_periods=3).sum()/R.rolling(20,min_periods=10).std()
mom=R.rolling(3,min_periods=3).sum()/R.rolling(20,min_periods=10).std()
# stress if median 5d return or positive breadth is weak; blend is interpretable and always cross-sectional
stress=((med.rolling(5,min_periods=5).sum()<0)|(breadth.rolling(5,min_periods=5).mean()<0.45))
F=rev.where(stress[:,None],mom) if False else rev.where(stress, mom)
rows=[]
for s in U:
 q=pd.DataFrame({'f':F[s],'y':R[s].shift(-1)});q['date']=q.index;rows.append(q.reset_index(drop=True))
A=pd.concat(rows,ignore_index=True).dropna(); obs=[]
for dt,g in A.groupby('date'):
 if len(g)>=8 and g.f.nunique()>1: obs.append((dt,spearmanr(g.f,g.y).statistic,len(g)))
O=pd.DataFrame(obs,columns=['date','ic','n']); x=O.ic
turn=F.rank(axis=1,pct=True).diff().abs().mean(axis=1).mean()*2
print('dates',len(O),'avgN',O.n.mean(),'coverage',len(A)/(R.shape[0]*15),'IC',x.mean(),'ICIR',x.mean()/x.std(ddof=1),'hit',(x>0).mean(),'turn',turn)
for lo,hi in [(2020,2022),(2023,2024),(2025,2026)]:
 z=O[(O.date.dt.year>=lo)&(O.date.dt.year<=hi)].ic;print('regime',lo,hi,'IC',z.mean(),'ICIR',z.mean()/z.std(ddof=1),'N',len(z))
for h in [5,10]:
 Y=[]
 for s in U:
  q=pd.DataFrame({'f':F[s],'y':D[s].close.pct_change(h).shift(-h)});q['date']=q.index;Y.append(q.reset_index(drop=True))
 B=pd.concat(Y,ignore_index=True).dropna();z=[]
 for dt,g in B.groupby('date'):
  if len(g)>=8 and g.f.nunique()>1:z.append(spearmanr(g.f,g.y).statistic)
 print('decay',h,'IC',np.mean(z),'ICIR',np.mean(z)/np.std(z,ddof=1))

