import pandas as pd,numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def dat(s):
 d=pd.read_csv('../persistent/stock_data/'+s+'.csv'); d.date=pd.to_datetime(d.date); return d[d.date<='2026-07-15'].set_index('date').close
P=pd.DataFrame({s:dat(s) for s in U}).sort_index(); R=P.pct_change()
# Relative reversal normalized by trailing realized volatility; rank robustly cross-sectionally.
for look in [3,5]:
 vol=R.rolling(20,min_periods=15).std()
 rel=R.rolling(look,min_periods=look).sum().sub(R.rolling(look,min_periods=look).sum().median(axis=1),axis=0)
 F=-rel/vol
 rows=[]
 for dt in R.index:
  z=pd.concat([F.loc[dt],R.shift(-1).loc[dt]],axis=1).dropna(); z.columns=['f','y']
  if len(z)>=8 and z.f.nunique()>1: rows.append((dt,spearmanr(z.f,z.y).statistic,len(z)))
 q=pd.DataFrame(rows,columns=['date','ic','n']).set_index('date'); ic=q.ic
 print('look',look,'dates',len(ic),'avgN',q.n.mean(),'coverage',q.n.sum()/(len(ic)*15),'IC',ic.mean(),'ICIR',ic.mean()/ic.std(),'hit',(ic>0).mean())
 for a,b in [('2020','2022'),('2023','2024'),('2025','2026')]:
  x=ic.loc[a:b];print('regime',a,b,'IC',x.mean(),'ICIR',x.mean()/x.std(),'n',len(x))
 for h in [5,10]:
  yy=sum(R.shift(-k) for k in range(1,h+1)); vals=[]
  for dt in R.index:
   z=pd.concat([F.loc[dt],yy.loc[dt]],axis=1).dropna()
   if len(z)>=8 and z.iloc[:,0].nunique()>1: vals.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
  x=pd.Series(vals).dropna();print('decay',h,x.mean(),x.mean()/x.std(),len(x))

import pandas as pd,numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def dat(s):
 d=pd.read_csv('../persistent/stock_data/'+s+'.csv');d.date=pd.to_datetime(d.date);return d[d.date<='2026-07-15'].set_index('date').close.sort_index()
prices={s:dat(s) for s in U}; dates=sorted(set().union(*[set(x.index) for x in prices.values()]))
R=pd.DataFrame({s:x.pct_change() for s,x in prices.items()})
for look in [3,5]:
 Fs={}; Fhs={}
 for s,x in prices.items():
  r=x.pct_change(); v=r.rolling(20,min_periods=15).std(); rr=r.rolling(look,min_periods=look).sum()
  Fs[s]=-rr/v; Fhs[s]=x.shift(-1)/x-1
 F=pd.DataFrame(Fs); FW=pd.DataFrame(Fhs)
 med=F.median(axis=1); F=F.sub(med,axis=0) # relative to factor cross-sectional median (equiv robust relative return after scaling)
 rows=[]
 for dt in F.index:
  z=pd.concat([F.loc[dt],FW.loc[dt]],axis=1).dropna();z.columns=['f','y']
  if len(z)>=8 and z.f.nunique()>1: rows.append((dt,spearmanr(z.f,z.y).statistic,len(z)))
 q=pd.DataFrame(rows,columns=['date','ic','n']).set_index('date');ic=q.ic
 print('look',look,'dates',len(ic),'avgN',q.n.mean(),'coverage',q.n.sum()/(len(ic)*15),'IC',ic.mean(),'ICIR',ic.mean()/ic.std(),'hit',(ic>0).mean())
 for a,b in [('2020','2022'),('2023','2024'),('2025','2026')]:
  x=ic.loc[a:b];print('regime',a,b,'IC',x.mean(),'ICIR',x.mean()/x.std(),'n',len(x))
 for h in [5,10]:
  vals=[]
  for s,x in prices.items(): Fhs[s]=x.shift(-h)/x-1
  fh=pd.DataFrame(Fhs)
  for dt in F.index:
   z=pd.concat([F.loc[dt],fh.loc[dt]],axis=1).dropna()
   if len(z)>=8 and z.iloc[:,0].nunique()>1:vals.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
  xx=pd.Series(vals).dropna();print('decay',h,xx.mean(),xx.mean()/xx.std(),len(xx))

import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; END=pd.Timestamp('2026-07-15'); D={}
for s in U:
 d=get_stock_daily_data(s,days=3000)
 if d is not None:
  d=d[pd.to_datetime(d.date)<=END].copy(); d['date']=pd.to_datetime(d.date); D[s]=d.set_index('date')
# Novel: gap reversal, prior overnight gap (open/prev close), normalized by 20d vol; predicts next close return
cl=pd.concat({s:d.close for s,d in D.items()},axis=1).sort_index().ffill(); op=pd.concat({s:d.open for s,d in D.items()},axis=1).sort_index().reindex(cl.index).ffill(); r=cl.pct_change(); v=r.rolling(20,min_periods=10).std()
gap=op/cl.shift(1)-1
f=(-gap/v).replace([np.inf,-np.inf],np.nan)
out=[]; cov=[]; turn=[]; dec5=[]; dec10=[]
for i in range(len(cl)-10):
 q=pd.concat([f.iloc[i].rename('f'),r.iloc[i+1].rename('y')],axis=1).dropna()
 if len(q)>=8 and q.f.nunique()>1 and q.y.nunique()>1:
  out.append(spearmanr(q.f,q.y).statistic); cov.append(len(q)/len(U))
  for h,a in [(5,dec5),(10,dec10)]:
   z=pd.concat([f.iloc[i].rename('f'),cl.pct_change(h).iloc[i+h].rename('y')],axis=1).dropna()
   if len(z)>=8 and z.f.nunique()>1 and z.y.nunique()>1:a.append(spearmanr(z.f,z.y).statistic)
  if i:
   z=pd.concat([f.iloc[i],f.iloc[i-1]],axis=1).dropna()
   if len(z)>=8:turn.append((z.iloc[:,0].rank()!=z.iloc[:,1].rank()).mean())
x=np.asarray(out); print('dates',len(x),'assets',len(D),'avg_names',np.mean(cov)*len(U),'coverage',np.mean(cov),'IC',x.mean(),'ICIR',x.mean()/x.std(ddof=1),'hit',(x>0).mean(),'turn',np.mean(turn),'d5',np.mean(dec5),'d10',np.mean(dec10),'start',cl.index.min(),'end',cl.index.max())
for name,z in [('early',x[:len(x)//2]),('late',x[len(x)//2:]),('recent250',x[-250:])]: print(name,len(z),z.mean(),z.mean()/z.std(ddof=1),(z>0).mean())

