import pandas as pd,numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
 d=pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).set_index('date').sort_index()
 D[s]=d.close.loc[:'2026-07-15']
p=pd.concat([D[s].rename(s) for s in U],axis=1); r=p.pct_change(fill_method=None)
# downside semivolatility: focus on adverse shocks, improving scale for asymmetric assets
neg=r.where(r<0)
down=neg.rolling(20,min_periods=10).std()
# 3-day shock reversal, scaled by recent downside risk; winsorize cross-section for robustness
raw=-r.rolling(3,min_periods=3).sum()/down
fac=raw.clip(lower=raw.quantile(.05,axis=1),upper=raw.quantile(.95,axis=1),axis=0)
def evaluate(y, idx=None):
 out=[]
 for dt in (fac.index if idx is None else idx):
  z=pd.concat([fac.loc[dt],y.loc[dt]],axis=1).dropna()
  if len(z)>=8: out.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
 q=np.array(out)
 return len(q),float(q.mean()),float(q.mean()/q.std(ddof=1)),float(np.mean(q>0))
fwd=r.shift(-1); print('universe',len(U),'dates',len(p),'daily',evaluate(fwd))
for h in [3,5,10]: print(str(h)+'d',evaluate(p.pct_change(h,fill_method=None).shift(-h)))
prev=None; tr=[]; ns=[]
for dt in fac.index:
 z=fac.loc[dt].dropna(); ns.append(len(z)/15)
 q=z.rank(pct=True)
 if prev is not None: tr.append(np.mean(abs(q-prev.reindex(q.index).fillna(.5))))
 prev=q
print('coverage',np.nanmean(ns),'turnover',np.nanmean(tr))
for a,b in [('2020','2022'),('2023','2024'),('2025','2026')]: print(a+'-'+b,evaluate(fwd,fac.loc[a:b].index))
print('last',fac.dropna(how='all').index[-1].date())

